defined('ABSPATH')||exit;final class SPL_Plugin{public function run(){add_action('init',array('SPL_Activator','register'));(new SPL_Frontend())->hooks();(new SPL_Interactions())->hooks();(new SPL_Admin())->hooks();(new SPL_Privacy())->hooks();(new SPL_SEO())->hooks();add_action('wp_enqueue_scripts',array($this,'assets'));add_action('template_redirect',array($this,'headers'));}public function assets(){global$post;$m=(array)get_option('spl_page_map',array());if(!is_singular(SPL_Helpers::TYPE)&&!($post instanceof WP_Post&&in_array($post->ID,array_map('absint',$m),true)))return;wp_enqueue_style('spl',SPL_URL.'assets/library.css',array(),SPL_VERSION);wp_enqueue_script('spl',SPL_URL.'assets/library.js',array(),SPL_VERSION,true);wp_localize_script('spl','splData',array('url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('spl_action')));}public function headers(){$m=(array)get_option('spl_page_map',array());foreach(array('saved','reading')as$k)if(!empty($m[$k])&&is_page($m[$k])){nocache_headers();return;}}}

